const root = $input.item.json || {};
const headers = root.headers || {};
const pick = (name) => headers[name] || headers[name.toLowerCase()] || headers[name.toUpperCase()] || '';
const auth = String(pick('authorization') || '');
const bearer = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';
const provided = String(pick('x-order-intake-token') || bearer || '').trim();
const expected = String($vars.ORDER_INTAKE_TOKEN || '').trim();
return { json: {
  ...root,
  auth_ok: Boolean(expected && provided && provided === expected),
  auth_reason: !expected ? 'missing_server_token_var_ORDER_INTAKE_TOKEN' : !provided ? 'missing_token_header' : provided === expected ? '' : 'bad_token',
  checked_at_utc: new Date().toISOString(),
} };

const crypto = require('crypto');
const rootValue = $input.item.json;
const root = rootValue && typeof rootValue === 'object' && !Array.isArray(rootValue) ? rootValue : {};
const bodyValue = Object.prototype.hasOwnProperty.call(root, 'body') ? root.body : root;
const bodyIsObject = Boolean(bodyValue && typeof bodyValue === 'object' && !Array.isArray(bodyValue));
const body = bodyIsObject ? bodyValue : {};
const collapse = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const esc = (value) => collapse(value).replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const hash = (value) => crypto.createHash('sha256').update(String(value)).digest('hex');
const hasOffset = (value) => /(?:Z|[+-]\d\d:\d\d)$/.test(String(value || ''));
const eventAtRaw = collapse(body.event_at_utc || body.created_at_utc || body.updated_at_utc || '');
const now = new Date().toISOString();
const eventAt = eventAtRaw && hasOffset(eventAtRaw) && !Number.isNaN(Date.parse(eventAtRaw)) ? new Date(eventAtRaw).toISOString() : '';
const tenantKey = collapse(body.tenant_key || body.tenant_id || '').toLowerCase();
const orderId = collapse(body.order_id || body.order_number || body.id || '');
const customerName = collapse(body.customer_name || body.name || 'Customer');
const customerEmail = collapse(body.customer_email || body.email || '').toLowerCase();
const verifierValue = body.customer_status_token ?? body.status_token ?? body.verifier ?? '';
const verifierRaw = typeof verifierValue === 'string' ? verifierValue : '';
const verifier = verifierRaw.trim();
const verifierExact = verifierRaw === verifier;
const verifierStrong = verifier.length >= 24 && verifier.length <= 256;
const initialStatus = collapse(body.status || body.initial_status || 'Received');
const sourceRole = 'intake';
const sourceChannel = 'order-intake-webhook';
const sourceEvent = collapse(body.source_event_id || body.event_id || '');
const lineItems = Array.isArray(body.line_items) ? body.line_items : [];
const notes = collapse(body.order_notes || body.notes || '');
const errors = [];
if (!bodyIsObject) errors.push('request_body_must_be_object');
if (!tenantKey) errors.push('missing_tenant_key');
if (!orderId) errors.push('missing_order_id');
if (!eventAt) errors.push('timestamp_missing_explicit_offset');
if (!sourceEvent) errors.push('missing_event_id');
if (!verifier) errors.push('missing_customer_status_token');
if (verifier && !verifierExact) errors.push('customer_status_token_must_not_have_padding');
if (verifier && !verifierStrong) errors.push('customer_status_token_must_be_24_to_256_chars');
if (!['Received', 'Confirmed'].includes(initialStatus)) errors.push('bad_initial_status');
const orderKey = tenantKey && orderId ? hash('order-tracker:order:' + tenantKey + ':' + orderId.toLowerCase()) : '';
const eventKey = orderKey && sourceEvent
  ? hash('order-tracker:intake:' + orderKey + ':' + sourceEvent)
  : hash('order-tracker:bad-intake:' + now + ':' + JSON.stringify(body).slice(0, 200));
const notificationKey = orderKey ? hash('order-tracker:notify:' + orderKey + ':' + initialStatus + ':v1') : '';
return { json: {
  tenant_key: tenantKey,
  order_id: orderId,
  order_key: orderKey,
  customer_key: orderKey ? hash('order-tracker:customer:' + tenantKey + ':' + customerEmail + ':' + customerName.toLowerCase()) : '',
  customer_name: customerName,
  customer_name_html: esc(customerName),
  customer_email_hash: customerEmail ? hash('email:' + customerEmail) : '',
  customer_verifier_hash: verifierExact && verifierStrong && orderKey ? hash('order-tracker-verifier:' + orderKey + ':' + verifier) : '',
  requested_status: initialStatus,
  status_rank: initialStatus === 'Confirmed' ? 20 : 10,
  source_role: sourceRole,
  source_channel: sourceChannel,
  source_event_id: sourceEvent,
  event_at_utc: eventAt || now,
  event_key: eventKey,
  transition_key: orderKey ? hash('order-tracker:transition:' + orderKey + ':create:' + initialStatus) : '',
  notification_key: notificationKey,
  reason: collapse(body.reason || 'Order received'),
  reason_html: esc(body.reason || 'Order received'),
  order_notes: notes,
  order_notes_html: esc(notes),
  line_items_json: JSON.stringify(lineItems).slice(0, 9000),
  validation_errors: errors,
  smoke_tag: collapse(body.smoke_tag || ''),
  now_utc: now,
} };

const root = $input.item.json || {};
const headers = root.headers || {};
const pick = (name) => headers[name] || headers[name.toLowerCase()] || headers[name.toUpperCase()] || '';
const auth = String(pick('authorization') || '');
const bearer = auth.toLowerCase().startsWith('bearer ') ? auth.slice(7).trim() : '';
const provided = String(pick('x-order-status-token') || bearer || '').trim();
const expected = String($vars.ORDER_STATUS_TOKEN || '').trim();
return { json: {
  ...root,
  auth_ok: Boolean(expected && provided && provided === expected),
  auth_reason: !expected ? 'missing_server_token_var_ORDER_STATUS_TOKEN' : !provided ? 'missing_token_header' : provided === expected ? '' : 'bad_token',
  checked_at_utc: new Date().toISOString(),
} };

const crypto = require('crypto');
const rootValue = $input.item.json;
const root = rootValue && typeof rootValue === 'object' && !Array.isArray(rootValue) ? rootValue : {};
const bodyValue = Object.prototype.hasOwnProperty.call(root, 'body') ? root.body : root;
const bodyIsObject = Boolean(bodyValue && typeof bodyValue === 'object' && !Array.isArray(bodyValue));
const body = bodyIsObject ? bodyValue : {};
const collapse = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const hash = (value) => crypto.createHash('sha256').update(String(value)).digest('hex');
const hasOffset = (value) => /(?:Z|[+-]\d\d:\d\d)$/.test(String(value || ''));
const now = new Date().toISOString();
const tenantKey = collapse(body.tenant_key || body.tenant_id || '').toLowerCase();
const orderId = collapse(body.order_id || body.order_number || body.id || '');
const eventAtRaw = collapse(body.event_at_utc || body.updated_at_utc || '');
const eventAt = eventAtRaw && hasOffset(eventAtRaw) && !Number.isNaN(Date.parse(eventAtRaw)) ? new Date(eventAtRaw).toISOString() : '';
const orderKey = tenantKey && orderId ? hash('order-tracker:order:' + tenantKey + ':' + orderId.toLowerCase()) : '';
const status = collapse(body.status || body.to_status || '');
const sourceRole = 'internal';
const sourceChannel = 'status-update-webhook';
const sourceEvent = collapse(body.source_event_id || body.event_id || '');
const errors = [];
if (!bodyIsObject) errors.push('request_body_must_be_object');
if (bodyIsObject && Object.prototype.hasOwnProperty.call(body, 'events')) errors.push('events_array_not_supported');
if (!tenantKey) errors.push('missing_tenant_key');
if (!orderId) errors.push('missing_order_id');
if (!status) errors.push('missing_status');
if (!eventAt) errors.push('timestamp_missing_explicit_offset');
if (!sourceEvent) errors.push('missing_event_id');
const eventKey = orderKey && sourceEvent
  ? hash('order-tracker:status:' + orderKey + ':' + sourceEvent)
  : hash('order-tracker:bad-status:' + now + ':' + JSON.stringify(body).slice(0, 200));
return [{ json: {
  tenant_key: tenantKey,
  order_id: orderId,
  order_key: orderKey,
  requested_status: status,
  source_role: sourceRole,
  source_channel: sourceChannel,
  source_event_id: sourceEvent,
  event_at_utc: eventAt || now,
  event_key: eventKey,
  notification_key: orderKey ? hash('order-tracker:notify:' + orderKey + ':' + status + ':v1') : '',
  reason: collapse(body.reason || ''),
  reason_html: collapse(body.reason || '').replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch])),
  validation_errors: errors,
  smoke_tag: collapse(body.smoke_tag || ''),
  now_utc: now,
} }];

const incoming = $items('Normalize Status Update').map((item) => item.json || {});
const lookups = $items('Find Status Order Rows').map((item) => item.json || {}).filter((row) => row.order_key);
const historyRows = $input.all().map((item) => item.json || {}).filter((row) => row.event_key);
const historyEventKeys = new Set(historyRows.map((row) => String(row.event_key)));
const rowsByKey = new Map();
for (const row of lookups) rowsByKey.set(String(row.order_key), row);
const RANK = { 'Received': 10, 'Needs Clarification': 15, 'Confirmed': 20, 'Blocked': 25, 'In Production': 30, 'Backordered': 35, 'Quality Hold': 35, 'Ready': 40, 'Shipped': 50, 'Collected': 60, 'Cancelled': 90, 'Lost / Closed': 95 };
const TERMINAL = new Set(['Collected', 'Cancelled', 'Lost / Closed']);
const TRUSTED_TERMINAL_ROLES = new Set(['internal', 'system', 'admin']);
const ALLOWED_EDGES = {
  'Received': ['Confirmed', 'Cancelled'],
  'Needs Clarification': ['Received', 'Confirmed', 'Cancelled'],
  'Confirmed': ['In Production', 'Blocked', 'Backordered', 'Cancelled'],
  'Blocked': ['Confirmed', 'In Production', 'Cancelled'],
  'Backordered': ['Confirmed', 'In Production', 'Cancelled'],
  'In Production': ['Quality Hold', 'Ready', 'Blocked', 'Backordered', 'Cancelled'],
  'Quality Hold': ['In Production', 'Ready', 'Cancelled'],
  'Ready': ['Shipped', 'Collected', 'Cancelled'],
  'Shipped': ['Collected', 'Cancelled', 'Lost / Closed'],
  'Collected': [],
  'Cancelled': [],
  'Lost / Closed': [],
};
const allowed = new Set(Object.keys(RANK));
const now = new Date().toISOString();
const esc = (value) => String(value ?? '').replace(/\s+/g, ' ').trim().replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
return incoming.map((event) => {
  const order = rowsByKey.get(String(event.order_key || '')) || {};
  const current = order.customer_visible_status || '';
  const target = event.requested_status;
  const durableReplay = Boolean(event.event_key && historyEventKeys.has(String(event.event_key)));
  const latestEventReplay = Boolean(order.last_event_key && order.last_event_key === event.event_key);
  const replay = durableReplay || latestEventReplay;
  const errors = replay ? [] : [...(event.validation_errors || [])];
  const unchanged = Boolean(current && current === target && !replay);
  const eventAtMs = Date.parse(event.event_at_utc || '');
  const lastStatusAtMs = Date.parse(order.last_status_at_utc || '');
  if (!replay) {
    if (!allowed.has(target)) errors.push('unknown_status');
    if (!order.order_key) errors.push('order_not_found');
    if (Number.isFinite(eventAtMs) && Number.isFinite(lastStatusAtMs) && eventAtMs < lastStatusAtMs) errors.push('stale_status_event');
    if (event.source_role === 'customer' && target === 'Cancelled') errors.push('customer_cancelled_requires_confirmation');
    if (event.source_role === 'customer' && !['Needs Clarification', 'Cancelled'].includes(target)) errors.push('unauthorized_customer_status_write');
    if (event.source_role === 'carrier' && target !== 'Shipped') errors.push('unauthorized_carrier_status_write');
    if (!unchanged && TERMINAL.has(current) && target !== current) errors.push('terminal_state_blocks_transition');
    if (!unchanged && current === 'Shipped' && !['Collected', 'Cancelled', 'Lost / Closed'].includes(target)) errors.push('shipped_semterminal_blocks_transition');
    if (!unchanged && ['Collected', 'Cancelled', 'Lost / Closed'].includes(target) && !TRUSTED_TERMINAL_ROLES.has(event.source_role)) errors.push('terminal_target_requires_trusted_role');
    if (!unchanged && order.order_key && allowed.has(current) && allowed.has(target)) {
      const allowedTargets = ALLOWED_EDGES[current] || [];
      if (!allowedTargets.includes(target)) errors.push('transition_not_allowed_' + current.replace(/[^A-Za-z0-9]+/g, '_') + '_to_' + target.replace(/[^A-Za-z0-9]+/g, '_'));
    }
  }
  const shouldSend = errors.length === 0 && !replay && !unchanged;
  const reason = errors.length ? errors.join(',') : replay ? 'replay_duplicate_event' : unchanged ? 'unchanged_status' : (event.reason || 'Status updated');
  const rank = shouldSend ? (RANK[target] || Number(order.status_rank || 0)) : Number(order.status_rank || RANK[current] || RANK[target] || 0);
  const safeProjection = {
    order_id: event.order_id,
    status: shouldSend ? target : current || target,
    updated_at_utc: now,
    message: shouldSend ? 'Your order status changed to ' + target + '.' : 'No customer-visible status change was made.',
  };
  return {
    json: {
      ...order,
      order_key: event.order_key,
      order_id: event.order_id,
      customer_visible_status: shouldSend ? target : (current || target),
      internal_status: errors.length ? 'Held Status Update' : replay ? 'Replay Ignored' : unchanged ? 'Unchanged' : 'Open',
      status_rank: rank,
      source_channel: event.source_channel,
      source_role: event.source_role,
      last_event_key: shouldSend ? event.event_key : (order.last_event_key || ''),
      last_transition_key: shouldSend ? 'order-tracker:transition:' + event.order_key + ':' + current + ':' + target : (order.last_transition_key || ''),
      last_notified_status: order.last_notified_status || '',
      notification_status: shouldSend ? 'Pending Send' : (order.notification_status || 'No Send'),
      last_notification_key: shouldSend ? event.notification_key : (order.last_notification_key || ''),
      last_email_id: order.last_email_id || '',
      pending_since_utc: shouldSend ? now : (order.pending_since_utc || now),
      oldest_open_age_hours: 0,
      updated_at_utc: now,
      event_at_utc: event.event_at_utc,
      last_status_at_utc: shouldSend ? event.event_at_utc : (order.last_status_at_utc || event.event_at_utc),
      status_reason: reason,
      status_reason_html: esc(reason),
      safe_projection_json: JSON.stringify(safeProjection),
      last_execution_id: $execution.id,
      history_key: 'order-tracker:history:' + event.event_key,
      event_key: event.event_key,
      event_type: errors.length ? 'status_update_held' : replay ? 'status_update_replay' : unchanged ? 'status_update_unchanged' : 'status_changed',
      from_status: current,
      to_status: shouldSend ? target : (current || target),
      action: shouldSend ? 'update_order_and_notify' : errors.length ? 'held_status_update' : replay ? 'duplicate_replay_ignored' : 'unchanged_status_ignored',
      reason,
      reason_html: esc(reason),
      created_at_utc: now,
      notification_key: shouldSend ? event.notification_key : '',
      should_persist_transition: shouldSend,
      should_send_email: shouldSend,
      should_persist_hold: errors.length > 0,
      response_code: errors.length ? 422 : 200,
      response_status: shouldSend ? 'accepted_pending_controlled_email' : errors.length ? 'held_status_update' : replay ? 'duplicate_ignored' : 'unchanged_ignored',
      status: target,
      recipient_mode: 'controlled_inbox',
      controlled_recipient: 'ops@example.com',
      intended_recipient_hash: order.customer_email_hash || '',
      email_subject: '[ORDER STATUS] Order ' + event.order_id + ' ' + target,
      email_body_html: '<p>Order <strong>' + esc(event.order_id) + '</strong> is now <strong>' + esc(target) + '</strong>.</p><p>' + esc(reason) + '</p>',
      email_sent: false,
      test_email_id: '',
      status_before_send: target,
      smoke_tag: event.smoke_tag || order.smoke_tag || '',
    },
  };
});

const action = $('Filter Intake Sendable Notifications').item.json || {};
const sent = $input.item.json || {};
const emailId = String(sent.id || sent.messageId || sent.threadId || '').trim();
const sendFailed = Boolean(sent.error || (sent.message && sent.message.error) || sent.name === 'NodeApiError' || !emailId);
const now = new Date().toISOString();
return { json: {
  ...action,
  email_sent: !sendFailed,
  test_email_id: sendFailed ? '' : emailId,
  last_email_id: sendFailed ? (action.last_email_id || '') : emailId,
  last_notified_status: sendFailed ? (action.last_notified_status || '') : (action.customer_visible_status || action.to_status || action.status || ''),
  notification_status: sendFailed ? 'Pending Send' : 'Sent Controlled',
  pending_since_utc: action.pending_since_utc || now,
  oldest_open_age_hours: 0,
  updated_at_utc: now,
  last_execution_id: $execution.id,
  response_code: sendFailed ? 202 : (action.response_code || 202),
  response_status: sendFailed ? 'send_failed_pending_retry' : (action.response_status || 'sent_controlled'),
  send_error: sendFailed ? JSON.stringify(sent).slice(0, 500) : '',
} };

const action = $('Filter Status Sendable Notifications').item.json || {};
const sent = $input.item.json || {};
const emailId = String(sent.id || sent.messageId || sent.threadId || '').trim();
const sendFailed = Boolean(sent.error || (sent.message && sent.message.error) || sent.name === 'NodeApiError' || !emailId);
const now = new Date().toISOString();
return { json: {
  ...action,
  email_sent: !sendFailed,
  test_email_id: sendFailed ? '' : emailId,
  last_email_id: sendFailed ? (action.last_email_id || '') : emailId,
  last_notified_status: sendFailed ? (action.last_notified_status || '') : (action.customer_visible_status || action.to_status || action.status || ''),
  notification_status: sendFailed ? 'Pending Send' : 'Sent Controlled',
  pending_since_utc: action.pending_since_utc || now,
  oldest_open_age_hours: 0,
  updated_at_utc: now,
  last_execution_id: $execution.id,
  response_code: sendFailed ? 202 : (action.response_code || 202),
  response_status: sendFailed ? 'send_failed_pending_retry' : (action.response_status || 'sent_controlled'),
  send_error: sendFailed ? JSON.stringify(sent).slice(0, 500) : '',
} };

const item = $('Build Intake Sent Updates').item.json || {};
return { json: {
  ok: item.response_code < 400,
  status: item.response_status || item.action || 'ok',
  order_id: item.order_id || '',
  visible_status: item.customer_visible_status || item.to_status || '',
  reason: item.reason || item.status_reason || '',
} };

const item = $('Build Status Sent Updates').item.json || {};
const responseCode = Number(item.response_code || 202);
return { json: {
  ok: responseCode < 400,
  status: item.response_status || item.action || 'ok',
  order_id: item.order_id || '',
  visible_status: item.customer_visible_status || item.to_status || '',
  reason: item.reason || item.status_reason || '',
  response_code: responseCode,
} };

const item = $input.item.json || {};
return { json: {
  ok: item.response_code < 400,
  status: item.response_status || item.action || 'ok',
  order_id: item.order_id || '',
  visible_status: item.customer_visible_status || item.to_status || '',
  reason: item.reason || item.status_reason || '',
} };

const item = $input.item.json || {};
const unauthorized = item.auth_ok === false;
const responseCode = unauthorized ? 401 : Number(item.response_code || 200);
return { json: {
  ok: responseCode < 400,
  status: unauthorized ? 'unauthorized' : (item.response_status || item.action || 'ok'),
  order_id: item.order_id || '',
  visible_status: item.customer_visible_status || item.to_status || '',
  reason: unauthorized ? (item.auth_reason || 'unauthorized') : (item.reason || item.status_reason || ''),
  response_code: responseCode,
} };

const crypto = require('crypto');
const root = $input.item.json || {};
const body = root.body && typeof root.body === 'object' ? root.body : root;
const collapse = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const hash = (value) => crypto.createHash('sha256').update(String(value)).digest('hex');
const tenantKey = collapse(body.tenant_key || body.tenant_id || '').toLowerCase();
const orderId = collapse(body.order_id || body.order_number || body.id);
const verifier = collapse(body.customer_status_token || body.status_token || body.verifier);
const orderKey = tenantKey && orderId ? hash('order-tracker:order:' + tenantKey + ':' + orderId.toLowerCase()) : '';
return { json: {
  tenant_key: tenantKey,
  order_id: orderId,
  order_key: orderKey,
  provided_verifier_hash: verifier && orderKey ? hash('order-tracker-verifier:' + orderKey + ':' + verifier) : '',
  lookup_ok: Boolean(tenantKey && orderId && verifier),
} };

const lookup = $('Normalize Status Lookup').item.json || {};
const rows = $input.all().map((item) => item.json || {}).filter((row) => row.order_key);
const row = rows.find((item) => item.order_key === lookup.order_key);
const authorized = Boolean(row && lookup.lookup_ok && row.customer_verifier_hash && row.customer_verifier_hash === lookup.provided_verifier_hash);
if (!authorized) {
  return { json: { ok: false, status: 'not_found', reason: 'order_not_found_or_bad_verifier' } };
}
let projection = {};
try { projection = JSON.parse(row.safe_projection_json || '{}'); } catch (err) { projection = {}; }
return { json: {
  ok: true,
  status: 'found',
  order: {
    order_id: row.order_id,
    customer_visible_status: row.customer_visible_status,
    updated_at_utc: row.updated_at_utc,
    message: projection.message || 'Order status is available.',
  },
} };

const rows = $input.all().map((item) => item.json || {}).filter((row) => row.order_key);
const now = Date.now();
const stale = rows.map((row) => {
  const started = Date.parse(row.pending_since_utc || row.updated_at_utc || '');
  const age = Number.isFinite(started) ? (now - started) / 36e5 : 0;
  return { ...row, pending_age_hours: age };
}).filter((row) => row.notification_status === 'Pending Send' && row.pending_age_hours >= 2);
if (!stale.length) return [];
const oldest = Math.max(...stale.map((row) => row.pending_age_hours));
const htmlRows = stale.map((row) => '<li>' + String(row.order_id).replace(/[&<>"']/g, '') + ': ' + String(row.customer_visible_status).replace(/[&<>"']/g, '') + ' pending ' + row.pending_age_hours.toFixed(1) + 'h</li>').join('');
return [{ json: {
  stale_alert_needed: true,
  email_subject: '[ORDER STATUS] Stale order notification queue',
  report_html: '<p>Pending controlled emails need review.</p><ul>' + htmlRows + '</ul>',
  stale_count: stale.length,
  oldest_pending_age_hours: oldest,
} }];

const source = $items('Build Intake Actions').map((item) => item.json || {});
const sentKeys = new Set($input.all().map((item) => item.json || {}).filter((row) => row.notification_key && (row.email_sent === true || String(row.test_email_id || '').trim())).map((row) => row.notification_key));
return source.map((action) => {
  if (action.should_send_email && action.notification_key && sentKeys.has(action.notification_key)) {
    return { json: {
      ...action,
      should_send_email: false,
      should_persist_hold: false,
      action: 'notification_already_sent',
      response_code: 200,
      response_status: 'notification_already_sent',
      reason: 'notification_key_already_sent',
      reason_html: 'notification_key_already_sent',
      notification_status: 'Sent Controlled',
      pending_since_utc: action.pending_since_utc || action.updated_at_utc || new Date().toISOString(),
      ledger_dedup_hit: true,
    } };
  }
  return { json: action };
});

const source = $items('Build Status Actions').map((item) => item.json || {});
const sentByKey = new Map();
for (const item of $input.all()) {
  const row = item.json || {};
  const messageId = String(row.test_email_id || '').trim();
  const provesSent = row.email_sent === true || Boolean(messageId);
